--
--	@(#) $GenPackageDir$/$GenFileName$
$MssDoubleDashScriptLicense$
alter session set plsql_warnings = 'ENABLE:ALL';
/

create or replace function $lower DbSchemaName$.$sp_next_schemaidgen$
return smallint authid definer
is
	NextId smallint;
begin
	select cast( $lower DbSchemaName$.$lower DbColumnName$.nextval as smallint )
	into NextId
	from dual;

	return NextId;
end $sp_next_schemaidgen$;
/

show errors function $lower DbSchemaName$.$sp_next_schemaidgen$;

